```gleam
import gleam/list
import gleam/float
import gleam/int
import gleam/result

pub type Multivector {
  Multivector(
    scalar: Float,
    vector: List(Float),
    bivector: List(Float),
    trivector: List(Float),
    pseudoscalar: Float,
  )
}

pub type CliffordAlgebra {
  CliffordAlgebra(
    dimension: Int,
    signature: List(Int),
    basis_blades: List(String),
  )
}

pub type GeometricEmbedding {
  GeometricEmbedding(
    token_id: Int,
    multivector_rep: Multivector,
    conformal_point: List(Float),
    rotor: Multivector,
  )
}

fn list_at(lst: List(a), index: Int) -> Result(a, Nil) {
  case index < 0 {
    True -> Error(Nil)
    False -> {
      lst
      |> list.drop(index)
      |> list.first
    }
  }
}

pub fn create_clifford_algebra(dim: Int) -> CliffordAlgebra {
  let signature = list.repeat(1, dim)
  let basis_blades = generate_basis_blades(dim)

  CliffordAlgebra(
    dimension: dim,
    signature: signature,
    basis_blades: basis_blades,
  )
}

fn generate_basis_blades(dim: Int) -> List(String) {
  list.range(0, int.bitwise_shift_left(1, dim) - 1)
  |> list.map(fn(i) {
    list.range(0, dim - 1)
    |> list.filter(fn(j) {
      int.bitwise_and(i, int.bitwise_shift_left(1, j)) != 0
    })
    |> list.map(fn(idx) { "e" <> int.to_string(idx) })
    |> list.fold("", fn(acc, s) { acc <> s })
  })
}

pub fn geometric_product(a: Multivector, b: Multivector) -> Multivector {
  let scalar_part = a.scalar *. b.scalar
    -. dot_product(a.vector, b.vector)

  let vector_part = list.map2(a.vector, b.vector, fn(av, bv) {
    a.scalar *. bv +. b.scalar *. av
  })

  let bivector_part = outer_product(a.vector, b.vector)

  Multivector(
    scalar: scalar_part,
    vector: vector_part,
    bivector: bivector_part,
    trivector: [],
    pseudoscalar: 0.0,
  )
}

fn dot_product(a: List(Float), b: List(Float)) -> Float {
  list.zip(a, b)
  |> list.map(fn(pair) { pair.0 *. pair.1 })
  |> list.fold(0.0, float.add)
}

fn outer_product(a: List(Float), b: List(Float)) -> List(Float) {
  list.flat_map(a, fn(av) {
    list.map(b, fn(bv) { av *. bv })
  })
}

pub fn wedge_product(a: Multivector, b: Multivector) -> Multivector {
  let bivector_result = list.flat_map(a.vector, fn(av) {
    list.map(b.vector, fn(bv) { av *. bv })
  })

  Multivector(
    scalar: 0.0,
    vector: [],
    bivector: bivector_result,
    trivector: [],
    pseudoscalar: 0.0,
  )
}

pub fn inner_product(a: Multivector, b: Multivector) -> Float {
  a.scalar *. b.scalar +. dot_product(a.vector, b.vector)
}

pub fn clifford_conjugate(m: Multivector) -> Multivector {
  Multivector(
    scalar: m.scalar,
    vector: list.map(m.vector, fn(x) { -.x }),
    bivector: m.bivector,
    trivector: list.map(m.trivector, fn(x) { -.x }),
    pseudoscalar: -.m.pseudoscalar,
  )
}

pub fn multivector_norm(m: Multivector) -> Float {
  let conj = clifford_conjugate(m)
  let product = geometric_product(m, conj)
  float.square_root(product.scalar) |> result.unwrap(1.0)
}

pub fn normalize_multivector(m: Multivector) -> Multivector {
  let norm = multivector_norm(m)
  case norm >. 0.0 {
    True -> Multivector(
      scalar: m.scalar /. norm,
      vector: list.map(m.vector, fn(x) { x /. norm }),
      bivector: list.map(m.bivector, fn(x) { x /. norm }),
      trivector: list.map(m.trivector, fn(x) { x /. norm }),
      pseudoscalar: m.pseudoscalar /. norm,
    )
    False -> m
  }
}

pub fn rotor_from_angle_plane(angle: Float, bivector: List(Float)) -> Multivector {
  let half_angle = angle /. 2.0
  let cos_half = float.cos(half_angle) |> result.unwrap(1.0)
  let sin_half = float.sin(half_angle) |> result.unwrap(0.0)

  let norm = float.square_root(
    list.fold(bivector, 0.0, fn(acc, x) { acc +. x *. x })
  ) |> result.unwrap(1.0)

  let normalized_bivector = case norm >. 0.0 {
    True -> list.map(bivector, fn(x) { x /. norm })
    False -> bivector
  }

  Multivector(
    scalar: cos_half,
    vector: [],
    bivector: list.map(normalized_bivector, fn(x) { -.sin_half *. x }),
    trivector: [],
    pseudoscalar: 0.0,
  )
}

pub fn apply_rotor(rotor: Multivector, point: Multivector) -> Multivector {
  let rotor_inv = clifford_conjugate(rotor)
  let temp = geometric_product(rotor, point)
  geometric_product(temp, rotor_inv)
}

pub fn conformal_embedding(point: List(Float)) -> Multivector {
  let n = list.length(point)
  let point_squared = list.fold(point, 0.0, fn(acc, x) { acc +. x *. x })

  let e_minus = 0.5 *. { 1.0 -. point_squared }
  let e_plus = 0.5 *. { 1.0 +. point_squared }

  let conformal_vector = list.append(
    point,
    [e_minus, e_plus],
  )

  Multivector(
    scalar: 0.0,
    vector: conformal_vector,
    bivector: [],
    trivector: [],
    pseudoscalar: 0.0,
  )
}

pub fn extract_euclidean(conformal: Multivector) -> List(Float) {
  case list.length(conformal.vector) > 2 {
    True -> {
      list.take(conformal.vector, list.length(conformal.vector) - 2)
    }
    False -> conformal.vector
  }
}

pub fn create_geometric_embedding(
  token_id: Int,
  base_embedding: List(Float),
  algebra: CliffordAlgebra,
) -> GeometricEmbedding {
  let mv = Multivector(
    scalar: 1.0,
    vector: base_embedding,
    bivector: [],
    trivector: [],
    pseudoscalar: 0.0,
  )

  let normalized_mv = normalize_multivector(mv)
  let conformal_pt = conformal_embedding(base_embedding)
  let rotor = rotor_from_angle_plane(float.pi /. 4.0, [1.0, 0.0])

  GeometricEmbedding(
    token_id: token_id,
    multivector_rep: normalized_mv,
    conformal_point: extract_euclidean(conformal_pt),
    rotor: rotor,
  )
}

pub fn geometric_attention(
  query: GeometricEmbedding,
  key: GeometricEmbedding,
  value: GeometricEmbedding,
) -> GeometricEmbedding {
  let q_mv = query.multivector_rep
  let k_mv = key.multivector_rep
  let v_mv = value.multivector_rep

  let attention_score = inner_product(q_mv, k_mv)
  let softmax_score = float.exp(attention_score) |> result.unwrap(1.0)

  let attended_mv = Multivector(
    scalar: v_mv.scalar *. softmax_score,
    vector: list.map(v_mv.vector, fn(x) { x *. softmax_score }),
    bivector: list.map(v_mv.bivector, fn(x) { x *. softmax_score }),
    trivector: list.map(v_mv.trivector, fn(x) { x *. softmax_score }),
    pseudoscalar: v_mv.pseudoscalar *. softmax_score,
  )

  GeometricEmbedding(
    token_id: value.token_id,
    multivector_rep: attended_mv,
    conformal_point: value.conformal_point,
    rotor: value.rotor,
  )
}

pub fn geometric_transformation(
  embedding: GeometricEmbedding,
  rotor: Multivector,
) -> GeometricEmbedding {
  let transformed_mv = apply_rotor(rotor, embedding.multivector_rep)

  GeometricEmbedding(
    token_id: embedding.token_id,
    multivector_rep: transformed_mv,
    conformal_point: embedding.conformal_point,
    rotor: geometric_product(embedding.rotor, rotor),
  )
}

pub fn batch_geometric_embeddings(
  token_ids: List(Int),
  base_embeddings: List(List(Float)),
  dim: Int,
) -> List(GeometricEmbedding) {
  let algebra = create_clifford_algebra(dim)

  list.zip(token_ids, base_embeddings)
  |> list.map(fn(pair) {
    create_geometric_embedding(pair.0, pair.1, algebra)
  })
}

pub fn geometric_layer_forward(
  embeddings: List(GeometricEmbedding),
  rotor: Multivector,
) -> List(GeometricEmbedding) {
  list.map(embeddings, fn(emb) {
    geometric_transformation(emb, rotor)
  })
}
