```gleam
import gleam/list
import gleam/float
import gleam/int
import gleam/result

pub type QuantumState {
  QuantumState(
    amplitudes: List(Complex),
    num_qubits: Int,
    measurement_basis: String,
  )
}

pub type Complex {
  Complex(real: Float, imag: Float)
}

pub type QuantumCircuit {
  QuantumCircuit(
    gates: List(QuantumGate),
    num_qubits: Int,
    parameters: List(Float),
  )
}

pub type QuantumGate {
  Hadamard(qubit: Int)
  PauliX(qubit: Int)
  PauliY(qubit: Int)
  PauliZ(qubit: Int)
  RotationX(qubit: Int, angle: Float)
  RotationY(qubit: Int, angle: Float)
  RotationZ(qubit: Int, angle: Float)
  CNOT(control: Int, target: Int)
  CZ(control: Int, target: Int)
  Toffoli(control1: Int, control2: Int, target: Int)
  PhaseShift(qubit: Int, phase: Float)
  CustomUnitary(qubit: Int, matrix: List(List(Complex)))
}

pub type ParameterShiftRule {
  ParameterShiftRule(
    parameter_index: Int,
    shift_amount: Float,
    coefficient: Float,
  )
}

pub fn complex_add(a: Complex, b: Complex) -> Complex {
  Complex(real: a.real +. b.real, imag: a.imag +. b.imag)
}

pub fn complex_subtract(a: Complex, b: Complex) -> Complex {
  Complex(real: a.real -. b.real, imag: a.imag -. b.imag)
}

pub fn complex_multiply(a: Complex, b: Complex) -> Complex {
  Complex(
    real: a.real *. b.real -. a.imag *. b.imag,
    imag: a.real *. b.imag +. a.imag *. b.real,
  )
}

pub fn complex_conjugate(c: Complex) -> Complex {
  Complex(real: c.real, imag: -.c.imag)
}

pub fn complex_magnitude(c: Complex) -> Float {
  float.square_root(c.real *. c.real +. c.imag *. c.imag)
  |> result.unwrap(0.0)
}

pub fn complex_scale(c: Complex, scalar: Float) -> Complex {
  Complex(real: c.real *. scalar, imag: c.imag *. scalar)
}

pub fn create_zero_state(num_qubits: Int) -> QuantumState {
  let state_size = int.bitwise_shift_left(1, num_qubits)
  let amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    case i {
      0 -> Complex(real: 1.0, imag: 0.0)
      _ -> Complex(real: 0.0, imag: 0.0)
    }
  })

  QuantumState(
    amplitudes: amplitudes,
    num_qubits: num_qubits,
    measurement_basis: "computational",
  )
}

pub fn apply_gate(state: QuantumState, gate: QuantumGate) -> QuantumState {
  case gate {
    Hadamard(qubit) -> apply_hadamard(state, qubit)
    PauliX(qubit) -> apply_pauli_x(state, qubit)
    PauliY(qubit) -> apply_pauli_y(state, qubit)
    PauliZ(qubit) -> apply_pauli_z(state, qubit)
    RotationX(qubit, angle) -> apply_rotation_x(state, qubit, angle)
    RotationY(qubit, angle) -> apply_rotation_y(state, qubit, angle)
    RotationZ(qubit, angle) -> apply_rotation_z(state, qubit, angle)
    CNOT(control, target) -> apply_cnot(state, control, target)
    CZ(control, target) -> apply_cz(state, control, target)
    PhaseShift(qubit, phase) -> apply_phase_shift(state, qubit, phase)
    _ -> state
  }
}

fn apply_hadamard(state: QuantumState, qubit: Int) -> QuantumState {
  let sqrt2_inv = 1.0 /. float.square_root(2.0) |> result.unwrap(0.707)
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    let i_without_qubit = int.bitwise_and(i, int.bitwise_not(qubit_mask))
    let i_with_qubit = int.bitwise_or(i_without_qubit, qubit_mask)

    let amp0 = list.drop(state.amplitudes, i_without_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))
    let amp1 = list.drop(state.amplitudes, i_with_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))

    case int.bitwise_and(i, qubit_mask) == 0 {
      True -> complex_scale(complex_add(amp0, amp1), sqrt2_inv)
      False -> complex_scale(complex_subtract(amp0, amp1), sqrt2_inv)
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_pauli_x(state: QuantumState, qubit: Int) -> QuantumState {
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    let flipped_i = int.bitwise_xor(i, qubit_mask)
    list.drop(state.amplitudes, flipped_i)
    |> list.first
    |> result.unwrap(Complex(real: 0.0, imag: 0.0))
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_pauli_y(state: QuantumState, qubit: Int) -> QuantumState {
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    let flipped_i = int.bitwise_xor(i, qubit_mask)
    let amp = list.drop(state.amplitudes, flipped_i)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))

    case int.bitwise_and(i, qubit_mask) == 0 {
      True -> Complex(real: amp.imag, imag: -.amp.real)
      False -> Complex(real: -.amp.imag, imag: amp.real)
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_pauli_z(state: QuantumState, qubit: Int) -> QuantumState {
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(state.amplitudes, fn(amp, i) {
    case int.bitwise_and(i, qubit_mask) != 0 {
      True -> Complex(real: -.amp.real, imag: -.amp.imag)
      False -> amp
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_rotation_x(state: QuantumState, qubit: Int, angle: Float) -> QuantumState {
  let cos_half = float.cos(angle /. 2.0) |> result.unwrap(1.0)
  let sin_half = float.sin(angle /. 2.0) |> result.unwrap(0.0)
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    let i_without_qubit = int.bitwise_and(i, int.bitwise_not(qubit_mask))
    let i_with_qubit = int.bitwise_or(i_without_qubit, qubit_mask)

    let amp0 = list.drop(state.amplitudes, i_without_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))
    let amp1 = list.drop(state.amplitudes, i_with_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))

    case int.bitwise_and(i, qubit_mask) == 0 {
      True -> complex_add(
        complex_scale(amp0, cos_half),
        Complex(real: -.sin_half *. amp1.imag, imag: -.sin_half *. amp1.real),
      )
      False -> complex_add(
        Complex(real: -.sin_half *. amp0.imag, imag: -.sin_half *. amp0.real),
        complex_scale(amp1, cos_half),
      )
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_rotation_y(state: QuantumState, qubit: Int, angle: Float) -> QuantumState {
  let cos_half = float.cos(angle /. 2.0) |> result.unwrap(1.0)
  let sin_half = float.sin(angle /. 2.0) |> result.unwrap(0.0)
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let qubit_mask = int.bitwise_shift_left(1, qubit)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    let i_without_qubit = int.bitwise_and(i, int.bitwise_not(qubit_mask))
    let i_with_qubit = int.bitwise_or(i_without_qubit, qubit_mask)

    let amp0 = list.drop(state.amplitudes, i_without_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))
    let amp1 = list.drop(state.amplitudes, i_with_qubit)
      |> list.first
      |> result.unwrap(Complex(real: 0.0, imag: 0.0))

    case int.bitwise_and(i, qubit_mask) == 0 {
      True -> complex_add(
        complex_scale(amp0, cos_half),
        complex_scale(amp1, -.sin_half),
      )
      False -> complex_add(
        complex_scale(amp0, sin_half),
        complex_scale(amp1, cos_half),
      )
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_rotation_z(state: QuantumState, qubit: Int, angle: Float) -> QuantumState {
  let qubit_mask = int.bitwise_shift_left(1, qubit)
  let phase_0 = Complex(
    real: float.cos(-.angle /. 2.0) |> result.unwrap(1.0),
    imag: float.sin(-.angle /. 2.0) |> result.unwrap(0.0),
  )
  let phase_1 = Complex(
    real: float.cos(angle /. 2.0) |> result.unwrap(1.0),
    imag: float.sin(angle /. 2.0) |> result.unwrap(0.0),
  )

  let new_amplitudes = list.index_map(state.amplitudes, fn(amp, i) {
    case int.bitwise_and(i, qubit_mask) == 0 {
      True -> complex_multiply(amp, phase_0)
      False -> complex_multiply(amp, phase_1)
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_cnot(state: QuantumState, control: Int, target: Int) -> QuantumState {
  let state_size = int.bitwise_shift_left(1, state.num_qubits)
  let control_mask = int.bitwise_shift_left(1, control)
  let target_mask = int.bitwise_shift_left(1, target)

  let new_amplitudes = list.index_map(list.range(0, state_size - 1), fn(_, i) {
    case int.bitwise_and(i, control_mask) != 0 {
      True -> {
        let flipped_i = int.bitwise_xor(i, target_mask)
        list.drop(state.amplitudes, flipped_i)
        |> list.first
        |> result.unwrap(Complex(real: 0.0, imag: 0.0))
      }
      False -> {
        list.drop(state.amplitudes, i)
        |> list.first
        |> result.unwrap(Complex(real: 0.0, imag: 0.0))
      }
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_cz(state: QuantumState, control: Int, target: Int) -> QuantumState {
  let control_mask = int.bitwise_shift_left(1, control)
  let target_mask = int.bitwise_shift_left(1, target)

  let new_amplitudes = list.index_map(state.amplitudes, fn(amp, i) {
    case int.bitwise_and(i, control_mask) != 0 && int.bitwise_and(i, target_mask) != 0 {
      True -> Complex(real: -.amp.real, imag: -.amp.imag)
      False -> amp
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

fn apply_phase_shift(state: QuantumState, qubit: Int, phase: Float) -> QuantumState {
  let qubit_mask = int.bitwise_shift_left(1, qubit)
  let phase_factor = Complex(
    real: float.cos(phase) |> result.unwrap(1.0),
    imag: float.sin(phase) |> result.unwrap(0.0),
  )

  let new_amplitudes = list.index_map(state.amplitudes, fn(amp, i) {
    case int.bitwise_and(i, qubit_mask) != 0 {
      True -> complex_multiply(amp, phase_factor)
      False -> amp
    }
  })

  QuantumState(..state, amplitudes: new_amplitudes)
}

pub fn execute_circuit(circuit: QuantumCircuit) -> QuantumState {
  let initial_state = create_zero_state(circuit.num_qubits)

  list.fold(circuit.gates, initial_state, fn(state, gate) {
    apply_gate(state, gate)
  })
}

pub fn parameter_shift_gradient(
  circuit: QuantumCircuit,
  observable: List(Complex),
  param_index: Int,
) -> Float {
  let shift = float.pi /. 2.0

  let shifted_params_plus = list.index_map(circuit.parameters, fn(p, i) {
    case i == param_index {
      True -> p +. shift
      False -> p
    }
  })

  let shifted_params_minus = list.index_map(circuit.parameters, fn(p, i) {
    case i == param_index {
      True -> p -. shift
      False -> p
    }
  })

  let circuit_plus = QuantumCircuit(..circuit, parameters: shifted_params_plus)
  let circuit_minus = QuantumCircuit(..circuit, parameters: shifted_params_minus)

  let state_plus = execute_circuit(circuit_plus)
  let state_minus = execute_circuit(circuit_minus)

  let expectation_plus = compute_expectation(state_plus, observable)
  let expectation_minus = compute_expectation(state_minus, observable)

  { expectation_plus -. expectation_minus } /. 2.0
}

fn compute_expectation(state: QuantumState, observable: List(Complex)) -> Float {
  list.zip(state.amplitudes, observable)
  |> list.map(fn(pair) {
    let amp = pair.0
    let obs = pair.1
    let product = complex_multiply(complex_conjugate(amp), obs)
    product.real
  })
  |> list.fold(0.0, float.add)
}

pub fn compute_all_gradients(
  circuit: QuantumCircuit,
  observable: List(Complex),
) -> List(Float) {
  list.index_map(circuit.parameters, fn(_, i) {
    parameter_shift_gradient(circuit, observable, i)
  })
}

pub fn quantum_natural_gradient(
  circuit: QuantumCircuit,
  gradients: List(Float),
  fisher_matrix: List(List(Float)),
) -> List(Float) {
  let fisher_inv = invert_matrix(fisher_matrix)
  matrix_vector_multiply(fisher_inv, gradients)
}

fn invert_matrix(matrix: List(List(Float))) -> List(List(Float)) {
  matrix
}

fn matrix_vector_multiply(matrix: List(List(Float)), vector: List(Float)) -> List(Float) {
  list.map(matrix, fn(row) {
    list.zip(row, vector)
    |> list.map(fn(pair) { pair.0 *. pair.1 })
    |> list.fold(0.0, float.add)
  })
}

pub fn vqe_optimization_step(
  circuit: QuantumCircuit,
  hamiltonian: List(Complex),
  learning_rate: Float,
) -> QuantumCircuit {
  let gradients = compute_all_gradients(circuit, hamiltonian)

  let updated_params = list.zip(circuit.parameters, gradients)
  |> list.map(fn(pair) {
    pair.0 -. learning_rate *. pair.1
  })

  QuantumCircuit(..circuit, parameters: updated_params)
}
